func TestNonLayerIIIAudioUsesFFmpeg(t *testing.T) {
	for _, tt := range []struct {
		name   string
		header byte
	}{
		{"MPEG4-ADTS.aac", 0xf1},
		{"MPEG2-ADTS.aac", 0xf9},
		{"MPEG1-LayerI.mp1", 0xff},
		{"MPEG1-LayerII.mp2", 0xfd},
	} {
		t.Run(tt.name, func(t *testing.T) {
			data := make([]byte, 16)
			copy(data, []byte{0xff, tt.header, 0x6c, 0x40})
			reader := bytes.NewReader(data)
			if _, ok, err := DecodeMP3If(reader); ok || err != nil {
				t.Errorf("non-Layer-III header recognized as MP3: ok=%v err=%v", ok, err)
			}
			if pos, err := reader.Seek(0, io.SeekCurrent); err != nil || pos != 0 {
				t.Errorf("probe did not rewind: pos=%d err=%v", pos, err)
			}
			opts := Options{SampleRate: 22050, FFmpegPath: installFakeFFmpeg(t)}
			pcm, err := DecodeBytes(data, opts)
			if err != nil || pcm.SampleRate != 22050 || !slices.Equal(pcm.Samples, []float64{0, 0.5}) {
				t.Errorf("byte input did not use ffmpeg: pcm=%+v err=%v", pcm, err)
			}
			path := filepath.Join(t.TempDir(), tt.name)
			if err := os.WriteFile(path, data, 0o644); err != nil {
				t.Fatal(err)
			}
			pcm, err = DecodeFile(path, opts)
			if err != nil || pcm.SampleRate != 22050 || !slices.Equal(pcm.Samples, []float64{0, 0.5}) {
				t.Errorf("file input did not use ffmpeg: pcm=%+v err=%v", pcm, err)
			}
		})
	}
}

func TestCorruptLayerIIIStillReturnsDecodeError(t *testing.T) {
	data := []byte{0xff, 0xfb, 0, 0, 0, 0, 0, 0}
	if _, ok, err := DecodeMP3If(bytes.NewReader(data)); !ok || err == nil {
		t.Fatalf("corrupt Layer III must remain a native decode error: ok=%v err=%v", ok, err)
	}
}

package dsp

import "testing"

func TestTempogramPreservesTempoWhenCapped(t *testing.T) {
	// A 120 BPM onset every 50 frames at 100 frames/second.
	spec := Spectrogram{Frames: 1200, Bins: 1, SampleRate: 8000, HopSize: 80, Values: make([]float64, 1200)}
	for frame := 25; frame < spec.Frames; frame += 50 {
		spec.Values[frame] = 1
	}
	full := Tempogram(&spec, 100, 140, 0)
	if full.At(600, 20) == 0 || full.At(600, 20) <= full.At(600, 0) {
		t.Fatal("fixture must have stronger 120 BPM than 100 BPM correlation")
	}
	for _, limit := range []int{1, 128, 256, 1200, 1300} {
		capped := Tempogram(&spec, 100, 140, limit)
		wantWidth := min(limit, spec.Frames)
		if capped.Width != wantWidth {
			t.Fatalf("limit %d: width %d, want %d", limit, capped.Width, wantWidth)
		}
		for x := 0; x < capped.Width; x++ {
			center := spec.Frames / 2
			if capped.Width > 1 {
				center = int(float64(x) * float64(spec.Frames-1) / float64(capped.Width-1))
			}
			for y := 0; y < capped.Height; y++ {
				if got, want := capped.At(x, y), full.At(center, y); got != want {
					t.Fatalf("limit %d, column %d, BPM %d: correlation %v, want %v at original frame %d", limit, x, y+100, got, want, center)
				}
			}
		}
	}
}

func TestTempogramEmpty(t *testing.T) {
	spec := Spectrogram{SampleRate: 8000, HopSize: 80}
	out := Tempogram(&spec, 100, 140, 256)
	if out.Width != 0 || len(out.Values) != 0 {
		t.Fatal("expected an empty tempogram")
	}
}

package audio

import (
	"bytes"
	"encoding/binary"
	"testing"
)

func TestDecodeWAVFloat32(t *testing.T) {
	buf := &bytes.Buffer{}
	buf.WriteString("RIFF")
	writeU32(buf, 4+(8+16)+(8+8))
	buf.WriteString("WAVE")

	buf.WriteString("fmt ")
	writeU32(buf, 16)
	writeU16(buf, 3)
	writeU16(buf, 1)
	writeU32(buf, 44100)
	writeU32(buf, 44100*4)
	writeU16(buf, 4)
	writeU16(buf, 32)

	buf.WriteString("data")
	writeU32(buf, 8)
	_ = binary.Write(buf, binary.LittleEndian, float32(0.5))
	_ = binary.Write(buf, binary.LittleEndian, float32(-0.25))

	pcm, err := DecodeBytes(buf.Bytes(), Options{})
	if err != nil {
		t.Fatalf("DecodeBytes: %v", err)
	}
	if len(pcm.Samples) != 2 {
		t.Fatalf("samples = %d", len(pcm.Samples))
	}
}

func TestDecodeWAVFloat64(t *testing.T) {
	buf := &bytes.Buffer{}
	buf.WriteString("RIFF")
	writeU32(buf, 4+(8+16)+(8+16))
	buf.WriteString("WAVE")

	buf.WriteString("fmt ")
	writeU32(buf, 16)
	writeU16(buf, 3)
	writeU16(buf, 1)
	writeU32(buf, 44100)
	writeU32(buf, 44100*8)
	writeU16(buf, 8)
	writeU16(buf, 64)

	buf.WriteString("data")
	writeU32(buf, 16)
	_ = binary.Write(buf, binary.LittleEndian, float64(0.5))
	_ = binary.Write(buf, binary.LittleEndian, float64(-0.25))

	pcm, err := DecodeBytes(buf.Bytes(), Options{})
	if err != nil {
		t.Fatalf("DecodeBytes: %v", err)
	}
	if len(pcm.Samples) != 2 {
		t.Fatalf("samples = %d", len(pcm.Samples))
	}
}

func writeU16(buf *bytes.Buffer, v uint16) {
	buf.WriteByte(byte(v))
	buf.WriteByte(byte(v >> 8))
}

func writeU32(buf *bytes.Buffer, v uint32) {
	buf.WriteByte(byte(v))
	buf.WriteByte(byte(v >> 8))
	buf.WriteByte(byte(v >> 16))
	buf.WriteByte(byte(v >> 24))
}
